create table if not exists public.maintenance_records (id bigint generated by default as identity primary key, polygon_id text not null, polygon_name text, turno integer, work_date date, work_time time, day_name text, status text default 'PENDIENTE', pct integer default 0 check (pct between 0 and 100), elaboro text, reviso text, activity text, observations text, photo_type text, photos jsonb default '[]'::jsonb, created_at timestamptz default now());
alter table public.maintenance_records enable row level security;
drop policy if exists "taesa public read" on public.maintenance_records; drop policy if exists "taesa public insert" on public.maintenance_records; drop policy if exists "taesa public update" on public.maintenance_records; drop policy if exists "taesa public delete" on public.maintenance_records;
create policy "taesa public read" on public.maintenance_records for select to anon using (true);
create policy "taesa public insert" on public.maintenance_records for insert to anon with check (true);
create policy "taesa public update" on public.maintenance_records for update to anon using (true) with check (true);
create policy "taesa public delete" on public.maintenance_records for delete to anon using (true);
grant select, insert, update, delete on public.maintenance_records to anon;
grant usage, select on sequence public.maintenance_records_id_seq to anon;
insert into storage.buckets (id,name,public) values ('taesa-fotos','taesa-fotos',true) on conflict (id) do update set public=true;
drop policy if exists "taesa public photos read" on storage.objects; drop policy if exists "taesa public photos insert" on storage.objects;
create policy "taesa public photos read" on storage.objects for select to anon using (bucket_id='taesa-fotos');
create policy "taesa public photos insert" on storage.objects for insert to anon with check (bucket_id='taesa-fotos');
